import sys, json

d = json.load(sys.stdin)["body"]
msgs = d.get("messages", [])
question = ""
for m in msgs:
    if m.get("origin") == "user":
        question = m.get("text", "")
        break

# Emit hop.rag_question (promoted to context.rag_question by the set_context edge)
# + a store-select tool_call as the body.
# IMPORTANT: op_select requires an explicit columns array (no SELECT *).
out = {
    "header": {
        "rag_question": question
    },
    "messages": [{
        "origin": "assistant",
        "type": "tool_call",
        "id": "q-sel",
        "text": json.dumps({"operation": "select", "table": "corpus", "columns": ["doc_id", "text"]})
    }]
}
sys.stdout.write(json.dumps(out))
